const float PHI = (sqrt( 5. ) + 1.) / 2.;
const float PI = acos( 0. ) * 2.;
const float T_CENTER = 0.25623058987490549; // looks like this is incorrect

mat2 rot( float a ) { return mat2( cos(a), sin(a), -sin(a), cos(a) ); }

// x in [0., .5]
int calcInnerness( float x, int depth )
{
  int ret = 0;
  while ( depth > 0 )
  {
     if ( x < .5 / PHI ) 
     {
        x = .5 - x * PHI;
        depth -= 1;
     }
     else
     {
        ret += ((depth & 1) == 1 ? 1 : -1);
        x = (.5 - x) / (2. - PHI);
        depth -= 2;            
     }
  }
  return ret;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord*2. - iResolution.xy) / iResolution.y;

    float col = 0.;

    float scale = 5.;
    uv /= scale;

    float t_offset = T_CENTER + sin( iTime * .3 ) * .05;

    float p0 = ((rot( 0. * .4 * PI ) * uv).x + t_offset);
    float p1 = ((rot( 1. * .4 * PI ) * uv).x + t_offset);
    float p2 = ((rot( 2. * .4 * PI ) * uv).x + t_offset);
    float p3 = ((rot( 3. * .4 * PI ) * uv).x + t_offset);
    float p4 = ((rot( 4. * .4 * PI ) * uv).x + t_offset);

    int DEPTH = 15;
    if ( p0 > 0. && p0 < .5 ) col += float( calcInnerness( p0, DEPTH ) );
    if ( p1 > 0. && p1 < .5 ) col += float( calcInnerness( p1, DEPTH ) );
    if ( p2 > 0. && p2 < .5 ) col += float( calcInnerness( p2, DEPTH ) );
    if ( p3 > 0. && p3 < .5 ) col += float( calcInnerness( p3, DEPTH ) );
    if ( p4 > 0. && p4 < .5 ) col += float( calcInnerness( p4, DEPTH ) );

    col = col * .03 + .5;

    fragColor = vec4( vec3( col ), 1. );
}
